/**
 * Contract-shaped fixtures for the acquisition page (contracts/acq_api_contract.md, v1.1).
 * MOCK BUILDS ONLY: scripts/check-no-mocks.mjs fails the real build if any marker below leaks.
 *
 * - summary.json is generated by generate_fixture.py from today's real files and checked
 *   against docs/gold_acquisition_model.md §12. Every value is real EXCEPT the three
 *   HR-sensitive spend categories (Team, PayrollExpenses, Freelance), which are
 *   SYNTHETIC placeholders (CDO-11: Finance-only): the real people total split 50/35/15.
 * - PLANTED_RUN_ID is a second, PLANTED run: the same data plus a synthetic 2024-11 month
 *   beyond `data_complete_through`, with no spend and `cost_null_reason: "spend_missing"`,
 *   so the "cost unavailable" state can be exercised without changing the real figures.
 * - Scenario rows behave like finora_gold.funnel_conversion_rate: append-only, the current
 *   rate of a transition is its latest row. `sql_demo_080` is the §12.6 test fixture;
 *   `proposal_close_045` is made up; `q4_typo` is a planted invalid scenario (GR-03).
 */
import type { AcqMonth, AcqSummary, Scenario, ScenarioRate } from "../../src/lib/acq/types";
import realSummary from "./summary.json";

