  won_by_industry: { RESTAURANTS: 12, MANUFACTURING: 9, RETAIL: 10, TECHNOLOGY: 4, PROFESSIONAL_SERVICES: 3, HEALTHCARE: 3 },
  won_by_industry_new_logo: { RESTAURANTS: 12, MANUFACTURING: 9, RETAIL: 10, TECHNOLOGY: 4, PROFESSIONAL_SERVICES: 3, HEALTHCARE: 3 },
